import { normalizeRanges } from './normalize-ranges.mjs';

function assertInputArray(name, ranges) {
  if (!Array.isArray(ranges)) {
    throw new TypeError(`${name} must be an array`);
  }
  for (const pair of ranges) {
    if (!Array.isArray(pair) || pair.length !== 2) {
      throw new TypeError('Each range must be an array of exactly two finite numbers');
    }
    const start = pair[0];
    const end = pair[1];
    if (
      typeof start !== 'number' ||
      typeof end !== 'number' ||
      !Number.isFinite(start) ||
      !Number.isFinite(end)
    ) {
      throw new TypeError('Each range must be an array of exactly two finite numbers');
    }
    if (start > end) {
      throw new RangeError('Range start must not exceed end');
    }
  }
}

export function subtractRanges(base, removed) {
  assertInputArray('base', base);
  assertInputArray('removed', removed);
  const baseNorm = normalizeRanges(base);
  const removedNorm = normalizeRanges(removed);
  let result = baseNorm.map(([start, end]) => [start, end]);
  for (const [cutStart, cutEnd] of removedNorm) {
    const next = [];
    for (const [start, end] of result) {
      if (cutEnd <= start || cutStart >= end) {
        next.push([start, end]);
        continue;
      }
      if (start < cutStart) {
        next.push([start, cutStart]);
      }
      if (end > cutEnd) {
        next.push([cutEnd, end]);
      }
    }
    result = next;
  }
  return result.map(([start, end]) => [start, end]);
}

